"use client";

import { motion } from "framer-motion";
import { useState } from "react";
import { manualControl } from "@/lib/api/droneCommand";
import { Spinner } from "@/components/ui/spinner";

export default function DroneController({
  droneId,
  currentAltitude = 0,
  onClose,
}) {
  const [altitude, setAltitude] = useState(currentAltitude);
  const [confirmOpen, setConfirmOpen] = useState(false);
  const [isLoading, setIsLoading] = useState(false);

  const send = async (command: string, value?: number) => {
    if (!droneId) return;

    try {
      setIsLoading(true);
      await manualControl({
        droneDbId: droneId,
        command,
        value,
      });
    } catch (err) {
      console.error("Manual control error:", err);
    } finally {
      setIsLoading(false);
    }
  };

  const handleAltitudeConfirm = async () => {
    await send("SET_ALTITUDE", altitude);
    setConfirmOpen(false);
  };

  const controlButton = (label: string, command: string, className = "") => (
    <button
      onClick={() => send(command)}
      disabled={isLoading}
      className={`
        h-12 min-w-[90px] rounded-lg font-medium text-sm transition-all duration-200
        border border-neutral-700 bg-neutral-800/50 text-gray-100
        hover:bg-neutral-700 hover:border-neutral-600 disabled:opacity-50
        active:scale-95 disabled:cursor-not-allowed
        ${className}
      `}
      aria-label={label}
      title={label}
    >
      {label}
    </button>
  );

  return (
    <motion.div
      drag
      dragMomentum={false}
      className="fixed z-[9999] bg-gradient-to-br from-neutral-900 to-neutral-950 backdrop-blur-xl border border-neutral-800 rounded-2xl p-6 shadow-2xl w-[900px] max-w-[95vw]"
      style={{
        top: "50%",
        left: "50%",
        translateX: "-50%",
        translateY: "-50%",
      }}
    >
      <div className="mb-6">
        <h2 className="text-lg font-semibold text-gray-100 mb-1">
          Flight Control Panel
        </h2>
        <p className="text-xs text-gray-500">Drag to move • Click to control</p>
      </div>
      <button
        onClick={onClose}
        className="absolute top-3 right-3 w-8 h-8 flex items-center justify-center rounded-lg 
  bg-neutral-800/60 hover:bg-neutral-700 border border-neutral-700 text-gray-400 hover:text-white 
  transition-all duration-200 active:scale-95"
        aria-label="Close controller"
      >
        ✕
      </button>
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
        {/* Header */}

        {/* Movement Section */}
        <div className="bg-neutral-800/40 border border-neutral-700 rounded-xl p-4 h-full flex flex-col">
          <h3 className="text-xs font-semibold text-gray-400 uppercase tracking-wider mb-3">
            Movement Controls
          </h3>

          <div className="flex flex-1 flex-col items-center justify-center gap-3">
            {controlButton("Forward", "FORWARD", "w-28")}

            <div className="flex gap-3">
              {controlButton("Left", "LEFT", "w-28")}
              {controlButton("Right", "RIGHT", "w-28")}
            </div>

            {controlButton("Backward", "BACKWARD", "w-28")}
          </div>
        </div>

        {/* Rotation Section */}
        <div className="bg-neutral-800/40 border border-neutral-700 rounded-xl p-4 h-full flex flex-col">
          <h3 className="text-xs font-semibold text-gray-400 uppercase tracking-wider mb-3">
            Rotation Controls
          </h3>

          <div className="flex flex-1 flex-col items-center justify-center gap-3">
            {controlButton("Ascend", "UP", "w-28")}

            <div className="flex gap-3">
              {controlButton("Rotate Left", "YAW_LEFT", "w-28")}
              {controlButton("Rotate Right", "YAW_RIGHT", "w-28")}
            </div>

            {controlButton("Descend", "DOWN", "w-28")}
          </div>
        </div>

        {/* Altitude Slider Section */}
        <div className="bg-neutral-800/40 border border-neutral-700 rounded-xl p-4 h-full flex flex-col">
          {/* Header */}
          <div className="flex justify-between items-center mb-4">
            <span className="text-sm text-gray-300">Target Altitude</span>
            <span className="text-lg font-semibold text-blue-400">
              {altitude} m
            </span>
          </div>

          {/* Content */}
          <div className="flex flex-1 items-stretch justify-between gap-6">
            {/* Vertical Slider */}
            <div className="flex flex-col items-center">
              <span className="text-xs text-gray-500 mb-2">100</span>

              <div className="h-40 flex items-center justify-center">
                <input
                  type="range"
                  min={0}
                  max={100}
                  value={altitude}
                  onChange={(e) => setAltitude(Number(e.target.value))}
                  disabled={isLoading}
                  className="w-32 h-2 appearance-none bg-neutral-700 rounded-lg cursor-pointer accent-blue-500 -rotate-90"
                />
              </div>

              <span className="text-xs text-gray-500 mt-2">0</span>
            </div>

            {/* Action side */}
            <div className="flex flex-col justify-end w-full max-w-[140px]">
              <button
                onClick={() => setConfirmOpen(true)}
                disabled={isLoading}
                className="w-full  mt-auto py-2 px-3 bg-blue-600 hover:bg-blue-700 disabled:opacity-50 rounded-lg text-sm font-medium text-white transition active:scale-95"
              >
                {isLoading ? (
                  <span className="flex items-center justify-center gap-2">
                    <Spinner className="w-4 h-4" />
                  </span>
                ) : (
                  "Apply"
                )}
              </button>
            </div>
          </div>
        </div>
      </div>

      {/* Confirmation Modal */}
      {confirmOpen && (
        <motion.div
          initial={{ opacity: 0, scale: 0.95 }}
          animate={{ opacity: 1, scale: 1 }}
          exit={{ opacity: 0, scale: 0.95 }}
          className="absolute inset-0 bg-black/50 rounded-2xl p-4 flex flex-col items-center justify-center"
        >
          <div className="bg-gradient-to-br from-neutral-800 to-neutral-900 border border-neutral-700 rounded-xl p-4 text-center max-w-xs">
            <h4 className="text-sm font-semibold text-gray-100 mb-2">
              Confirm Altitude Change
            </h4>
            <p className="text-2xl font-bold text-blue-400 mb-4 tabular-nums">
              {altitude} m
            </p>

            <div className="flex gap-3">
              <button
                onClick={handleAltitudeConfirm}
                disabled={isLoading}
                className="flex-1 py-2 px-3 bg-blue-600 hover:bg-blue-700 disabled:opacity-50 rounded-lg text-sm font-medium text-white transition-colors active:scale-95"
              >
                {isLoading ? <Spinner className="w-4 h-4" /> : "Confirm"}
              </button>
              <button
                onClick={() => setConfirmOpen(false)}
                disabled={isLoading}
                className="flex-1 py-2 px-3 bg-neutral-700 hover:bg-neutral-600 disabled:opacity-50 rounded-lg text-sm font-medium text-gray-200 transition-colors active:scale-95"
              >
                Cancel
              </button>
            </div>
          </div>
        </motion.div>
      )}
    </motion.div>
  );
}
